**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("macierz.txt");
    int m[5][5];
    for (int i = 0; i < 5; i++)
        for (int j = 0; j < 5; j++)
            plik >> m[i][j];

    int sw[5] = {}, sk[5] = {};
    for (int i = 0; i < 5; i++)
        for (int j = 0; j < 5; j++) {
            sw[i] += m[i][j];
            sk[j] += m[i][j];
        }

    cout << "Sumy wierszy:";
    for (int i = 0; i < 5; i++) cout << " " << sw[i];
    cout << endl;

    cout << "Sumy kolumn:";
    for (int j = 0; j < 5; j++) cout << " " << sk[j];
    cout << endl;

    cout << "Wiersz=Kolumna:";
    for (int k = 0; k < 5; k++)
        if (sw[k] == sk[k]) cout << " " << k + 1;
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Obliczamy sumy wierszy i kolumn w jednej podwojnej petli. Potem porownujemy sw[k] z sk[k] dla kazdego k.

Weryfikacja:
- Sumy wierszy: 1+3+2+4+5=15, 2+1+3+2+2=10, 4+2+5+1+3=15, 3+4+1+3+4=15, 5+0+4+2+1=12
- Sumy kolumn: 1+2+4+3+5=15, 3+1+2+4+0=10, 2+3+5+1+4=15, 4+2+1+3+2=12, 5+2+3+4+1=15
- sw[0]=15=sk[0]=15 -> 1, sw[1]=10=sk[1]=10 -> 2, sw[2]=15=sk[2]=15 -> 3, sw[3]=15!=sk[3]=12, sw[4]=12!=sk[4]=15
